#include <bits/stdc++.h>
using namespace std;

double compute_abs(double val) {
    return val < 0 ? -val : val;
}

int main() {
    int a, b, n;
    cin >> a >> b >> n;
    int x, y1, y2;
    double min_diff = 1e100;
    int answer_x = 0, answer_y = 0;
    for (int i = 1; i <= n; ++i) {
        x = i;
        y1 = static_cast<int>((double)a / b * i);
        y2 = y1 + 1;
        double diff1 = compute_abs((double)a / b - (double)y1 / x);
        double diff2 = compute_abs((double)a / b - (double)y2 / x);
        if (min_diff > diff1) {
            min_diff = diff1;
            answer_x = y1;
            answer_y = x;
        }
        if (min_diff > diff2) {
            min_diff = diff2;
            answer_x = y2;
            answer_y = x;
        }
    }
    cout << answer_x << "/" << answer_y << endl;
}
